import React from 'react';
import { Button } from 'antd';
import { LeftOutlined, RightOutlined } from '@ant-design/icons';
import { monthNames } from '../utils/calendarHelpers';

const CalendarNavigation = ({ currentMonth, currentYear, goToPrevMonth, goToNextMonth }) => {
  return (
    <div className="calendar-navigation">
      <Button icon={<LeftOutlined />} onClick={goToPrevMonth} />
      <span className="current-month">
        {monthNames[currentMonth]} {currentYear}
      </span>
      <Button icon={<RightOutlined />} onClick={goToNextMonth} />
    </div>
  );
};

export default CalendarNavigation;
